export const byId = (id:string) => QUALIA.find(q=>q.id===id);
export const bySystem = (sys:string) => QUALIA.filter(q=>q.system===sys);
export const momentPool = () => QUALIA.filter(q=>q.nature==='computed');
export const personPool = () => QUALIA.filter(q=>q.observes!=='moment' && q.nature!=='cast');
export const castPool = (sys:string) => QUALIA.filter(q=>q.nature==='cast' && q.system===sys);
export const tarotDeck = () => QUALIA.filter(q=>q.system==='tarot-major'||q.system==='tarot-minor');
export const measured = () => QUALIA.filter(q=>q.tier==='measured');
export const celebrated = () => QUALIA.filter(q=>q.tier==='celebrated');
export const CAST_SYSTEMS = ['tarot','iching-hexagram','rune-cast','orisha-cast'] as const;